def transform(grid):
    # Each cell position in a 2x2 patch in the repeated motif is denoised
    # by the majority value at the same row and column phase across copies.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        for c in range(w):
            if c % 3 == 2:
                continue
            vals = [grid[r][k] for k in range(c % 3, w, 3)]
            out[r][c] = max(set(vals), key=vals.count)
    return out

